"use client";

import * as React from "react";

import { type DobResult, formatDobInput, validateDob } from "../../lib/dob";
import { cn, controlClasses, Field, FieldBadge, useFieldState } from "./field";

export interface DOBInputProps
  extends Omit<
    React.ComponentProps<"input">,
    "value" | "defaultValue" | "onChange" | "type"
  > {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  onValidationChange?: (result: DobResult) => void;
  validateOn?: "blur" | "change";
  /** Reject anyone younger than this. 18 is the usual KYC floor. */
  minAge?: number;
  /** Show the computed age once the date is valid. Default `true`. */
  showAge?: boolean;
  label?: string;
  description?: string;
  containerClassName?: string;
}

export function DOBInput({
  value: controlledValue,
  defaultValue = "",
  onValueChange,
  onValidationChange,
  validateOn = "blur",
  minAge,
  showAge = true,
  label,
  description,
  className,
  containerClassName,
  id,
  onBlur,
  ...props
}: DOBInputProps) {
  const reactId = React.useId();
  const inputId = id ?? `dob-${reactId}`;
  const messageId = `${inputId}-message`;

  const validate = React.useCallback(
    (raw: string) => validateDob(raw, { minAge }),
    [minAge],
  );

  const field = useFieldState<DobResult>({
    value: controlledValue,
    defaultValue,
    onValueChange,
    onValidationChange,
    validate,
    // Slashes are inserted as you type, so DD/MM/YYYY is unambiguous on screen
    // even though the user only types digits.
    transform: formatDobInput,
    validateOn,
  });

  const age =
    showAge && field.result.valid && field.result.age !== undefined
      ? `${field.result.age} years`
      : undefined;

  return (
    <Field
      id={inputId}
      messageId={messageId}
      label={label}
      message={field.error ?? description}
      tone={field.error ? "error" : "muted"}
      className={containerClassName}
    >
      <div className="relative">
        <input
          {...props}
          id={inputId}
          type="text"
          inputMode="numeric"
          autoComplete="bday"
          placeholder={props.placeholder ?? "DD/MM/YYYY"}
          value={field.value}
          onChange={(event) => field.setValue(event.target.value)}
          onBlur={(event) => {
            field.markTouched();
            onBlur?.(event);
          }}
          aria-invalid={Boolean(field.error)}
          aria-describedby={messageId}
          className={cn(
            controlClasses({
              error: Boolean(field.error),
              success: field.success,
            }),
            "tracking-[0.14em]",
            age && "pr-28",
            className,
          )}
        />
        {age && <FieldBadge>{age}</FieldBadge>}
      </div>
    </Field>
  );
}

"use client";

import { type ClassValue, clsx } from "clsx";
import { CircleAlert, Info } from "lucide-react";
import * as React from "react";
import { twMerge } from "tailwind-merge";

/**
 * Shared by every bharat-ui field. Defined here rather than imported from a
 * project's `@/lib/utils` so that installing a component can never overwrite
 * the consumer's own utils file.
 */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export type FieldTone = "error" | "hint" | "muted";

export interface FieldProps {
  id: string;
  /** Id of the element holding the message; wire this into aria-describedby. */
  messageId: string;
  label?: string;
  /** Resolved message text — an error, a warning, or the fallback description. */
  message?: string;
  tone?: FieldTone;
  className?: string;
  children: React.ReactNode;
}

/** Label + control + message, with the aria plumbing already correct. */
export function Field({
  id,
  messageId,
  label,
  message,
  tone = "muted",
  className,
  children,
}: FieldProps) {
  return (
    <div className={cn("w-full", className)}>
      {label && (
        <label htmlFor={id} className="mb-1.5 block text-sm font-medium">
          {label}
        </label>
      )}

      {children}

      {message && (
        <p
          id={messageId}
          // Only errors interrupt a screen reader; hints are read on focus.
          role={tone === "error" ? "alert" : undefined}
          className={cn(
            "mt-1.5 flex items-start gap-1.5 text-xs",
            tone === "error"
              ? "text-red-600 dark:text-red-400"
              : "text-neutral-500 dark:text-neutral-400",
          )}
        >
          {tone === "error" ? (
            <CircleAlert className="mt-px size-3.5 shrink-0" aria-hidden />
          ) : tone === "hint" ? (
            <Info className="mt-px size-3.5 shrink-0" aria-hidden />
          ) : null}
          {message}
        </p>
      )}
    </div>
  );
}

/** Border/ring classes shared by every text control, keyed on validity. */
export function controlClasses(state: {
  error?: boolean;
  success?: boolean;
}): string {
  return cn(
    "h-10 w-full rounded-lg border bg-transparent px-3 py-2 font-mono text-sm outline-none transition",
    "placeholder:font-sans placeholder:text-neutral-400 dark:placeholder:text-neutral-600",
    "disabled:cursor-not-allowed disabled:opacity-50",
    "focus-visible:ring-[3px]",
    state.error
      ? "border-red-500 focus-visible:ring-red-500/20"
      : state.success
        ? "border-emerald-500 focus-visible:ring-emerald-500/20"
        : "border-neutral-300 focus-visible:border-neutral-900 focus-visible:ring-neutral-900/10 dark:border-neutral-700 dark:focus-visible:border-neutral-300 dark:focus-visible:ring-neutral-100/10",
  );
}

export interface ValidationLike {
  valid: boolean;
  error?: { message: string };
}

/**
 * The controlled/uncontrolled + touched + report-upward logic every field here
 * needs. Kept in one place so all of them behave identically: errors appear on
 * blur by default, then update live once the user has been warned.
 */
export function useFieldState<T extends ValidationLike>(options: {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  onValidationChange?: (result: T) => void;
  validate: (raw: string) => T;
  /** Optional input mask applied on every keystroke. */
  transform?: (raw: string) => string;
  validateOn?: "blur" | "change";
}) {
  const {
    value: controlled,
    defaultValue = "",
    onValueChange,
    onValidationChange,
    validate,
    transform,
    validateOn = "blur",
  } = options;

  const isControlled = controlled !== undefined;
  const [uncontrolled, setUncontrolled] = React.useState(defaultValue);
  const value = isControlled ? controlled : uncontrolled;
  const [touched, setTouched] = React.useState(false);

  const result = React.useMemo(() => validate(value), [value, validate]);

  // Report upward only when the outcome actually changes, so consumers can put
  // setState directly in the callback without a render loop.
  const lastReported = React.useRef<string>("");
  React.useEffect(() => {
    const key = JSON.stringify(result);
    if (key === lastReported.current) return;
    lastReported.current = key;
    onValidationChange?.(result);
  }, [result, onValidationChange]);

  const setValue = React.useCallback(
    (next: string) => {
      const masked = transform ? transform(next) : next;
      if (!isControlled) setUncontrolled(masked);
      onValueChange?.(masked);
    },
    [isControlled, onValueChange, transform],
  );

  const shouldValidate = validateOn === "change" || touched;
  const error =
    shouldValidate && value.trim() !== "" ? result.error?.message : undefined;

  return {
    value,
    setValue,
    result,
    touched,
    markTouched: () => setTouched(true),
    error,
    success: result.valid,
  };
}

/** Small right-aligned badge inside a control (bank name, entity type, …). */
export function FieldBadge({ children }: { children: React.ReactNode }) {
  return (
    <span className="pointer-events-none absolute right-2 top-1/2 flex max-w-[45%] -translate-y-1/2 items-center gap-1 truncate rounded-full bg-emerald-500/10 px-2 py-0.5 text-xs font-medium text-emerald-700 dark:text-emerald-400">
      {children}
    </span>
  );
}

/**
 * Date-of-birth validation for Indian KYC forms.
 *
 * India writes dates DD/MM/YYYY. `new Date("03/08/2006")` parses that as
 * 8 March in a US locale, silently — so this module never hands a
 * user-typed string to the Date constructor. It parses the parts itself and
 * verifies the date round-trips, which is also what catches 31/02.
 */

const DOB_RE = /^(\d{1,2})[/\-. ](\d{1,2})[/\-. ](\d{4})$/;

export type DobErrorCode =
  | "empty"
  | "bad_shape"
  | "bad_day"
  | "bad_month"
  | "impossible_date"
  | "in_future"
  | "too_old"
  | "under_age";

export interface DobResult {
  valid: boolean;
  /** ISO `YYYY-MM-DD` — what an API should receive. */
  iso?: string;
  day?: number;
  month?: number;
  year?: number;
  /** Completed years as of today. */
  age?: number;
  error?: { code: DobErrorCode; message: string };
}

function fail(code: DobErrorCode, message: string): DobResult {
  return { valid: false, error: { code, message } };
}

/** Completed years between `iso` and `asOf`. */
export function ageFrom(iso: string, asOf: Date = new Date()): number {
  const [y, m, d] = iso.split("-").map(Number);
  let age = asOf.getFullYear() - y;
  const beforeBirthday =
    asOf.getMonth() + 1 < m ||
    (asOf.getMonth() + 1 === m && asOf.getDate() < d);
  if (beforeBirthday) age -= 1;
  return age;
}

/** Insert slashes as the user types: `03082006` → `03/08/2006`. */
export function formatDobInput(raw: string): string {
  const digits = raw.replace(/\D/g, "").slice(0, 8);
  if (digits.length <= 2) return digits;
  if (digits.length <= 4) return `${digits.slice(0, 2)}/${digits.slice(2)}`;
  return `${digits.slice(0, 2)}/${digits.slice(2, 4)}/${digits.slice(4)}`;
}

export function validateDob(
  input: string,
  options: { minAge?: number; maxAge?: number; asOf?: Date } = {},
): DobResult {
  const { minAge, maxAge = 120, asOf = new Date() } = options;

  if (!input.trim()) return fail("empty", "Enter a date of birth.");

  const match = DOB_RE.exec(input.trim());
  if (!match)
    return fail("bad_shape", "Use DD/MM/YYYY — day first, then month.");

  const day = Number(match[1]);
  const month = Number(match[2]);
  const year = Number(match[3]);

  if (month < 1 || month > 12)
    return fail("bad_month", "Month must be between 1 and 12.");
  if (day < 1 || day > 31)
    return fail("bad_day", "Day must be between 1 and 31.");

  // Round-trip through UTC to reject 31/02 and friends without touching local
  // timezone rules.
  const date = new Date(Date.UTC(year, month - 1, day));
  const roundTrips =
    date.getUTCFullYear() === year &&
    date.getUTCMonth() === month - 1 &&
    date.getUTCDate() === day;
  if (!roundTrips) {
    return fail("impossible_date", `There's no ${day}/${month} in ${year}.`);
  }

  const iso = `${year}-${String(month).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
  const age = ageFrom(iso, asOf);
  const parts = { iso, day, month, year, age };

  if (age < 0)
    return { ...fail("in_future", "That date is in the future."), ...parts };
  if (age > maxAge) {
    return {
      ...fail("too_old", "Check the year — that's over 120 years ago."),
      ...parts,
    };
  }
  if (minAge !== undefined && age < minAge) {
    return {
      ...fail("under_age", `You must be at least ${minAge} to continue.`),
      ...parts,
    };
  }

  return { valid: true, ...parts };
}
